function mt_take()
	local d, r, s = mt_state()
	if s ~= 0 or r >= PTTM_DAILY_MAX then return end
	SetTask(PTTM_T_DAILY, d * 100 + r * 10 + 1)
	TaskNote(PTTM_DailyId(), 0, "Ly Ch©u")
	Msg2Player(format("NhËn vßng %d/9 Nam Minh Ly Háa: ®¸nh Ly Ch©u lÊy néi ®¬n.", r + 1))
end

function mt_done()
	local d, r, s = mt_state()
